Here is the commit message:
IB/mlx5: Add necessary delay drop assignment

Assign the statistics and configuration structure pointer on success.

Fixes: fe248c3a5837 ('IB/mlx5: Add delay drop configuration and statistics')
Signed-off-by: Maor Gottlieb <maorg@mellanox.com>
Signed-off-by: Leon Romanovsky <leon@kernel.org>
Signed-off-by: Doug Ledford <dledford@redhat.com>

Here is the root cause:
The bug was caused by the absence of an assignment for the statistics and configuration structure pointer (`dev->delay_drop.dbg`) upon successful initialization of the delay drop debug filesystem. This oversight could lead to the system not having access to the necessary configuration and statistics, potentially resulting in incorrect behavior or crashes when attempting to use the delay drop feature.

Here is the patch:

 static int delay_drop_debugfs_init(struct mlx5_ib_dev *dev)
 {
 	struct mlx5_ib_dbg_delay_drop *dbg;

 	if (!mlx5_debugfs_root)
 		return 0;

 	dbg = kzalloc(sizeof(*dbg), GFP_KERNEL);
 	if (!dbg)
 		return -ENOMEM;

 	dbg->dir_debugfs =
 		debugfs_create_dir("delay_drop",
 				   dev->mdev->priv.dbg_root);
 	if (!dbg->dir_debugfs)
 		return -ENOMEM;

 	dbg->events_cnt_debugfs =
 		debugfs_create_atomic_t("num_timeout_events", 0400,
 					dbg->dir_debugfs,
 					&dev->delay_drop.events_cnt);
 	if (!dbg->events_cnt_debugfs)
 		goto out_debugfs;

 	dbg->rqs_cnt_debugfs =
 		debugfs_create_atomic_t("num_rqs", 0400,
 					dbg->dir_debugfs,
 					&dev->delay_drop.rqs_cnt);
 	if (!dbg->rqs_cnt_debugfs)
 		goto out_debugfs;

 	dbg->timeout_debugfs =
 		debugfs_create_file("timeout", 0600,
 				    dbg->dir_debugfs,
 				    &dev->delay_drop,
 				    &fops_delay_drop_timeout);
 	if (!dbg->timeout_debugfs)
 		goto out_debugfs;

+	dev->delay_drop.dbg = dbg;
+
 	return 0;

 out_debugfs:
 	delay_drop_debugfs_cleanup(dev);
 	return -ENOMEM;
 }



